#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int n, k;
vector<vector<int>> adj;
vector<int> parent_node;
vector<int> order;

void bfs_order(int root) {
    order.clear();
    order.reserve(n);
    parent_node.assign(n + 1, 0);

    vector<int> q;
    q.reserve(n);
    q.push_back(root);
    parent_node[root] = -1;

    int head = 0;
    while (head < (int)q.size()) {
        int u = q[head++];
        order.push_back(u);
        for (int v : adj[u]) {
            if (v != parent_node[u]) {
                parent_node[v] = u;
                q.push_back(v);
            }
        }
    }
}

bool check(int R) {
    vector<int> max_uncovered(n + 1, 0);
    vector<int> min_center(n + 1, INF);
    int centers_used = 0;

    // Process nodes from leaves to root
    for (int i = n - 1; i >= 0; --i) {
        int u = order[i];

        if (max_uncovered[u] + min_center[u] <= R) {
            max_uncovered[u] = -INF;
        }

        if (max_uncovered[u] == R) {
            centers_used++;
            min_center[u] = 0;
            max_uncovered[u] = -INF;
        }

        int p = parent_node[u];
        if (p != -1) {
            if (max_uncovered[u] != -INF) {
                max_uncovered[p] = max(max_uncovered[p], max_uncovered[u] + 1);
            }
            if (min_center[u] != INF) {
                min_center[p] = min(min_center[p], min_center[u] + 1);
            }
        }
    }

    int root = order[0];
    if (max_uncovered[root] >= 0) {
        centers_used++;
    }

    return centers_used <= k;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n >> k)) return 0;

    adj.resize(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    bfs_order(1);

    int low = 0, high = n, ans = n;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";

    return 0;
}
